CREATE TABLE IF NOT EXISTS leaves (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    employee_name TEXT    NOT NULL,
    leave_date    DATE    NOT NULL,
    leave_type    TEXT
);

CREATE TABLE IF NOT EXISTS public_holidays (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    holiday_date DATE    NOT NULL,
    description  TEXT,
    location     TEXT
);

